 92→export async function runAgentEditLoop(
 93→  newMessage: string,
 94→  conversationHistory: { role: string; content: string }[],
 95→  callbacks: AgentCallbacks,
 96→  signal?: AbortSignal,
 97→  userSessionId?: string,
 98→): Promise<void> {
 99→  try {
100→    const response = await fetch('/api/chat/edit', {
101→      method: 'POST',
102→      headers: {
103→        'Content-Type': 'application/json',
104→        ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
105→      },
106→      body: JSON.stringify({
107→        new_message: newMessage,
108→        conversation_history: conversationHistory,
109→      }),
110→      signal,
111→    });
112→
113→    if (!response.ok) {
114→      const errorText = await response.text();
115→      callbacks.onError(`Server error: ${errorText}`);
116→      return;
117→    }
118→
119→    await streamSSE(response, callbacks, signal);
120→  } catch (e: unknown) {
121→    if (signal?.aborted) return;
122→    const msg = e instanceof Error ? e.message : 'Connection failed';
123→    callbacks.onError(msg);
124→  }
125→}
